package com.gathin.tvhome;
import org.junit.Test;import static org.junit.Assert.*;
public class DockStyleTest {
 @Test public void quickAccessProfileDoesNotOverwriteExistingColors(){assertEquals("quickaccess",DockStyle.mode("quickaccess"));assertNotEquals(DockStyle.TOP,DockStyle.key("quickaccess",DockStyle.TOP));assertEquals(DockStyle.TOP,DockStyle.key("glass",DockStyle.TOP));assertNotEquals(DockStyle.key("quickaccess",DockStyle.TOP),DockStyle.key("quickaccess",DockStyle.BOTTOM));}
 @Test public void materialProfilesShareOnlySelectionAndVisibility(){assertEquals(DockStyle.MODE,DockStyle.key("quickaccess",DockStyle.MODE));assertEquals(DockStyle.VISIBLE,DockStyle.key("quickaccess",DockStyle.VISIBLE));for(String key:new String[]{DockStyle.TOP,DockStyle.BOTTOM,DockStyle.TRANSPARENCY,DockStyle.RIM,DockStyle.RIM_COLOR,DockStyle.RIM_OPACITY,DockStyle.GLOSS,DockStyle.RADIUS}){assertTrue(DockStyle.key("quickaccess",key).startsWith(DockStyle.P));assertNotEquals(key,DockStyle.key("quickaccess",key));}}
 @Test public void legacyIsTheFallbackForMissingOrInvalidModes(){assertEquals("legacy",DockStyle.mode(null));assertEquals("legacy",DockStyle.mode("unknown"));assertEquals("glass",DockStyle.mode("glass"));assertEquals("gradient",DockStyle.mode("gradient"));}
 @Test public void transparencyAndShapeAreBounded(){DockStyle s=new DockStyle("solid",true,0x123456,0x222222,999,true,0x333333,-1,true,99);assertEquals(100,s.transparency);assertEquals(0,s.rimOpacity);assertEquals(60,s.radius);assertEquals(0xFF123456,s.top);}
 @Test public void alphaHasCorrectEndpointsAndKeepsColor(){assertEquals(0x00123456,DockStyle.alpha(0xFF123456,0));assertEquals(0xFF123456,DockStyle.alpha(0x00123456,100));assertEquals(128,DockStyle.alpha(0xFFFFFF,50)>>>24);}
 @Test public void colorMixPreservesEndpointsAndRoundsEachChannel(){assertEquals(0xFF123456,DockStyle.mix(0xFF123456,0xFFEEDDCC,0));assertEquals(0xFFEEDDCC,DockStyle.mix(0xFF123456,0xFFEEDDCC,1));assertEquals(0xFF808080,DockStyle.mix(0xFF000000,0xFFFFFFFF,.5f));}
 @Test public void customColorsAcceptOnlySixHexDigits(){assertEquals(Integer.valueOf(0xFF123ABC),DockStyle.parseHex(" #123aBc "));assertEquals(Integer.valueOf(0xFF123ABC),DockStyle.parseHex("123ABC"));for(String s:new String[]{null,"#fff","#12345678","112233;cmd","#12gg99","","0x123456"})assertNull(DockStyle.parseHex(s));assertEquals("#123ABC",DockStyle.hex(0xFF123ABC));}
}
